using QuantForge.Core;namespace QuantForge.Core.ArchitectureTests;public sealed class AndroidResearchSessionSummaryFileStoreTests{[Fact]public void Session_summary_round_trips_by_fingerprint(){var root=Path.Combine(Path.GetTempPath(),Guid.NewGuid().ToString("N"));try{var value=new AndroidResearchSessionSummary("SESSION","P","DATA","STRAT",AndroidResearchQueueState.Complete,"Complete",true,false);var store=new AndroidResearchSessionSummaryFileStore(root);store.Save(value);Assert.Equal(value,store.Load(value.SessionFingerprint));}finally{if(Directory.Exists(root))Directory.Delete(root,true);}}}
